ALTER TABLE public.studio_project ADD COLUMN event_id uuid UNIQUE REFERENCES public.event(id) ON DELETE CASCADE;
ALTER TABLE public.studio_project ALTER COLUMN document_schema_version SET DEFAULT 6;
ALTER TABLE public.studio_project DROP CONSTRAINT studio_project_document_schema_version_check;
